commit f8474100a79068f2bb8909478f22a40e0c4694d1
Author: missingbulb <73882448+missingbulb@users.noreply.github.com>
Date:   Tue Sep 15 12:12:41 2026 +0300

    Measure a dead agent claim from the holder's own silence (#2039)

    `staleClaimedDispatchIssues` read `issue.updated_at`, which any comment
    moves — a losing executor letting go, a person, a task's own bookkeeping —
    so a dead claim read as live and sat past the 3h its escalation comment
    promises. The routine fire API cannot answer whether the session is still
    running (the per-routine token grants no read access), so this reclaim is
    the only backstop under the agent phase.

    It now measures from `livenessAt`, the holder's own claim or heartbeat
    trail, with `updated_at` kept as the fallback for a claim with no liveness
    signal and for a comment read that did not answer. The janitor reads
    comments for claimed dispatch issues only — the same one-read-per-holder
    shape the scheduler's executing-leash reclaim already uses.

    Closes #2038


    Claude-Session: https://claude.ai/code/session_01AzTUWukxGBToUAS7p9Gb7d

    Co-authored-by: Claude <noreply@anthropic.com>

diff --git a/packs/claudinite-tasks/src/session/dispatch.mjs b/packs/claudinite-tasks/src/session/dispatch.mjs
index e74aa63..5dd6988 100644
--- a/packs/claudinite-tasks/src/session/dispatch.mjs
+++ b/packs/claudinite-tasks/src/session/dispatch.mjs
@@ -316,16 +316,36 @@ export function readyLabelOn(issue) {
 // what enforces it): a task may put `agent-running` on an issue IT owns — a
 // request its pipeline has claimed, which stays claimed while its PR is in review,
 // far longer than 3h — and only that task knows when its own claim is stale.
+//
+// SILENCE IS THE HOLDER'S, NOT THE ISSUE'S (#924). `livenessAt` is the shell's read
+// of when the session that holds this claim last signed for it — its own claim or
+// heartbeat comment, `lastLivenessAt` in `../items/heartbeat.mjs`. Measuring from
+// `updated_at` instead reads a dead claim as live, because any comment moves it: a
+// losing executor letting go, a person, the task's own bookkeeping. `updated_at` is
+// still the fallback, for an issue with no liveness signal at all and for a comment
+// read that did not answer — a read that fails is not a verdict that the holder is
+// dead.
 export function staleClaimedDispatchIssues(openIssues = [], now, { idleMs = 3 * 3600e3 } = {}) {
   const nowMs = new Date(now).getTime();
   return openIssues.filter((issue) => {
     if (!parseDispatchTitle(issue.title)) return false;
     const names = labelNames(issue);
     if (!names.includes(AGENT_RUNNING_LABEL) || names.includes(NEEDS_HUMAN_LABEL)) return false;
-    return nowMs - new Date(issue.updated_at ?? issue.created_at).getTime() > idleMs;
+    const lastSign = issue.livenessAt ?? issue.updated_at ?? issue.created_at;
+    return nowMs - new Date(lastSign).getTime() > idleMs;
   });
 }

+// The claims a janitor run must read comments for before it can judge them —
+// `livenessAt`'s scope. Every open dispatch claim, so a candidate set narrowed by
+// the very clock the rule stopped trusting cannot narrow it wrongly; the count is
+// the health line's `running`, a handful.
+export const claimedDispatchIssues = (openIssues = []) => openIssues.filter((issue) => {
+  if (!parseDispatchTitle(issue.title)) return false;
+  const names = labelNames(issue);
+  return names.includes(AGENT_RUNNING_LABEL) && !names.includes(NEEDS_HUMAN_LABEL);
+});
+
 // The comment the shell posts when it reclaims a dead session's claim.
 export function staleClaimComment(issue) {
   const parsed = parseDispatchTitle(issue.title);
diff --git a/packs/claudinite-tasks/tasks/task-janitor/worker.mjs b/packs/claudinite-tasks/tasks/task-janitor/worker.mjs
index 7566052..d6f34a7 100644
--- a/packs/claudinite-tasks/tasks/task-janitor/worker.mjs
+++ b/packs/claudinite-tasks/tasks/task-janitor/worker.mjs
@@ -27,12 +27,14 @@
 import { pathToFileURL } from 'node:url';
 import {
   staleDispatchIssues, staleEscalationComment, staleClaimedDispatchIssues, staleClaimComment,
+  claimedDispatchIssues,
   rearmDispatchIssues, readyLabelOn, DISPATCH_PREFIX, NEEDS_HUMAN_LABEL, AGENT_RUNNING_LABEL,
   SCHEDULER_LABELS,
 } from '../../src/session/dispatch.mjs';
+import { lastLivenessAt } from '../../src/items/heartbeat.mjs';
 import { makeGh } from '../../src/world/github.mjs';
 import { ensureLabels } from '../../src/world/github.mjs';
-import { searchIssues, comment, addLabel, removeLabel } from '../../src/world/github.mjs';
+import { searchIssues, comment, addLabel, removeLabel, listComments } from '../../src/world/github.mjs';

 const item = process.env.CLAUDINITE_ITEM || '';
 const log = (s) => console.log(`task-janitor${item ? ` [#${item}]` : ''}: ${s}`);
@@ -56,6 +58,14 @@ export async function openDispatchIssues(gh, repo) {
 export async function sweep(gh, repo, now) {
   const open = await openDispatchIssues(gh, repo);
   const result = { open: open.length, stale: [], deadClaims: [], rearmed: [] };
+
+  // One comment read per CLAIMED dispatch issue — the same read the scheduler's
+  // executing-leash reclaim makes, for the same reason: the dead-claim rule
+  // measures the holder's own silence, and only its comments carry that.
+  for (const issue of claimedDispatchIssues(open)) {
+    issue.livenessAt = lastLivenessAt(await listComments(gh, repo, issue.number));
+  }
+
   const stale = staleDispatchIssues(open, now);
   const staleNumbers = new Set(stale.map((i) => i.number));
   const deadClaims = staleClaimedDispatchIssues(open, now).filter((i) => !staleNumbers.has(i.number));

