{
  "id": "git-pull-on-shallow-clone",
  "severity": "blocking",
  "since": "2026-09-06",
  "scope": "action",
  "failureMessage": "the clones here are shallow, so git pull finds no common ancestor, and nothing of value is ever on this repo's local main",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/(^|[;&|]\\s*|\\n\\s*)git\\s+pull\\b/",
      "what": "a git pull",
      "fix": "git fetch origin main && git reset --hard origin/main"
    }
  ]
}
{
  "id": "merge-main-into-branch",
  "severity": "blocking",
  "since": "2026-09-06",
  "scope": "action",
  "failureMessage": "a merge commit trips the blocking squash-merge-history check; the branch re-verifies against a moved main by rebasing",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/(^|[;&|]\\s*|\\n\\s*)git\\s+merge\\s+(origin\\/)?(main|master)\\b/",
      "what": "a merge of main into the branch",
      "fix": "git rebase origin/main"
    }
  ]
}
{
  "id": "github-api-via-shell",
  "severity": "blocking",
  "since": "2026-09-06",
  "scope": "action",
  "failureMessage": "there is no gh CLI here, and every repo-scoped api.github.com call 403s (\"GitHub access is not enabled for this session\"), so a shell poll reports \"still running\" until it times out",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/(^|[;&|]\\s*|\\n\\s*)((do|then|else)\\s+)?((curl|wget)\\b[^;&|\\n]*api\\.github\\.com|gh\\s)/",
      "what": "a GitHub read through the shell: \"{match}\"",
      "fix": "read the head sha's check runs with the GitHub MCP tools (pull_request_read get_check_runs, get_check_run)"
    },
    {
      "tool": "Monitor",
      "inputField": "command",
      "match": "/(^|[;&|]\\s*|\\n\\s*)((do|then|else)\\s+)?((curl|wget)\\b[^;&|\\n]*api\\.github\\.com|gh\\s)/",
      "what": "a Monitor polling GitHub through the shell: \"{match}\"",
      "fix": "read the head sha's check runs with the GitHub MCP tools on a rolling backoff; a shell poll here never sees the run finish"
    }
  ]
}
{
  "id": "bare-sleep-wait",
  "severity": "advisory",
  "scope": "action",
  "failureMessage": "a padded sleep waits on nothing nameable; a guard that would not stand as the whole test is sleeping and calling it polling",
  "fix": "name the condition awaited \u2014 a run's status, a file's arrival, a deadline \u2014 and wait on that",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/(^|[;&|]\\s*)sleep\\s+\\d+\\s*($|[;&|])/",
      "what": "a bare \"{match}\""
    },
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/\\bfor\\b[^;\\n]*;\\s*do\\s+sleep\\s+\\d+\\s*;\\s*done\\b/",
      "what": "a counted loop with nothing but a sleep in its body: \"{match}\""
    }
  ]
}
{
  "id": "test-suite-command-form",
  "severity": "advisory",
  "scope": "action",
  "failureMessage": "a bash glob without globstar reached 37 of 65 files and said nothing; node --test <dir> at least fails outright with Cannot find module",
  "fix": "node --test $(git ls-files '*.test.mjs')",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/\\bnode\\s+--test\\s+[^\\s;&|]*\\*/",
      "unlessMatches": "/git ls-files/",
      "what": "the suite run through a glob: \"{match}\""
    },
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/\\bnode\\s+--test\\s*($|[;&|>])/",
      "what": "node --test with no files named"
    }
  ]
}
{
  "id": "commit-all-sweeps-edits",
  "severity": "advisory",
  "scope": "action",
  "failureMessage": "git commit -a stages every modified file, and a later branch -D discards the in-progress edits it swept up",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/(^|[;&|]\\s*|\\n\\s*)git\\s+commit\\b[^;&|\\n]*\\s-a(m)?\\b/",
      "what": "a commit with -a",
      "fix": "stage the files this commit is about by name; isolate pending edits first"
    }
  ]
}
{
  "id": "cross-repo-verify-line",
  "severity": "advisory",
  "scope": "action",
  "since": "2026-09-06",
  "failureMessage": "the executor reads only this repository: its sessions carry no member's scope and its probes fetch anonymously, so this verification can never pass",
  "guardToolCalls": [
    {
      "tool": "mcp__github__issue_write",
      "inputField": "body",
      "match": "/^(Verify|In-production-when):[^\\n]*\\bmissingbulb\\/(?!Claudinite\\b)[\\w.-]+/m",
      "what": "a verification line reading another repository: \"{match}\"",
      "fix": "reproduce the premise on an object this repo owns, or file the verification on that repo"
    },
    {
      "tool": "mcp__github__issue_write",
      "inputField": "body",
      "match": "/^(Live-probe|Verify-probe):[^\\n]*api\\.github\\.com/m",
      "what": "a probe fetching the GitHub API: \"{match}\"",
      "fix": "probe a public raw or Pages URL instead, or make it a Verify: line about this repository"
    }
  ]
}
{
  "id": "add-repo-for-a-public-clone",
  "severity": "advisory",
  "scope": "action",
  "since": "2026-09-06",
  "failureMessage": "add_repo attaches nothing the git proxy does not already serve for a public repository",
  "guardToolCalls": [
    {
      "tool": "mcp__Claude_Code_Remote__add_repo",
      "inputField": "repo",
      "match": "/./",
      "what": "an add_repo for \"{field}\"",
      "fix": "for a public repository's files, git clone --depth 1 (about two seconds); add_repo only for a private one, or for its issues and pull requests"
    }
  ]
}
{
  "id": "scratch-screenshot-caption",
  "severity": "advisory",
  "scope": "action",
  "since": "2026-09-06",
  "failureMessage": "an image rendered from a scratch harness reads as the product unless its caption says otherwise",
  "guardToolCalls": [
    {
      "tool": "SendUserFile",
      "inputMatches": "/scratchpad[^\"]*\\.(png|jpe?g|gif|webp|svg)\\b/i",
      "unlessInputMatches": "/\"caption\":\"[^\"]*(harness|scratch)/i",
      "what": "a screenshot from the scratchpad sent without saying it came from a scratch harness",
      "fix": "say in the caption that it is rendered from a scratch test harness, not just what the widget shows"
    }
  ]
}
{
  "id": "checkout-restores-index",
  "severity": "advisory",
  "scope": "action",
  "since": "2026-09-06",
  "failureMessage": "git checkout -- restores from the index, destroying uncommitted work as thoroughly as the mutation it undoes",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/(^|[;&|]\\s*|\\n\\s*)git\\s+(checkout\\s+--|restore\\s|stash\\b)/",
      "what": "a working-tree restore: \"{match}\"",
      "fix": "commit or stage the real edit first, and only mutate a file whose current state you are ready to throw away"
    }
  ]
}
{
  "id": "settings-json-reserialized",
  "severity": "advisory",
  "scope": "action",
  "since": "2026-09-06",
  "failureMessage": "a JSON round trip rewrites indent, key order and escapes while nothing fails and tests stay green",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/JSON\\.stringify\\([^\\n]*\\.claudinite-settings\\.json|\\.claudinite-settings\\.json[^\\n]*JSON\\.stringify|json\\.dump\\([^\\n]*settings|settings[^\\n]*json\\.dump\\(/",
      "what": "a settings file rewritten by re-serialising it: \"{match}\"",
      "fix": "patch the file as anchored text instead"
    }
  ]
}
{
  "id": "busy-wait-loop",
  "severity": "blocking",
  "since": "2026-09-11",
  "scope": "action",
  "failureMessage": "a loop body of `:` yields nothing, so the shell spins at full tilt and the session answers nobody until a person interrupts it",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/(^|[;&|]\\s*|\\n\\s*)(until|while)\\b[^\\n]*;\\s*do\\s*(:|true)\\s*;\\s*done\\b/",
      "what": "a loop that spins without waiting: \"{match}\"",
      "fix": "sleep inside the loop body and bound the wait \u2014 or drop the loop: a background task's completion arrives as a notification"
    }
  ]
}
{
  "id": "mount-path-in-the-canon-home",
  "severity": "blocking",
  "since": "2026-09-13",
  "scope": "action",
  "failureMessage": "the canon home carries no .claudinite/shared/ at all, so a module invoked through that path is Cannot find module and the sweep the session believed it ran never ran",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/(^|[;&|(]\\s*|\\n\\s*)(?:[A-Za-z_][A-Za-z0-9_]*=[^\\s;&|]*\\s+)*(node|bash|sh)\\s+(--test\\s+)?\\.claudinite\\/shared\\//",
      "unlessMatches": "/(^|[;&|(]\\s*|\\n\\s*)cd\\s|PROJECT_DIR|--root|<<|\\|\\|\\s*(node|bash|sh)\\s/",
      "what": "an engine module run through the mount: \"{match}\"",
      "fix": "drop the prefix and run it from the repo root (node engine/checks/check_the_world.mjs); a member's checkout cloned into this session keeps the mount path, and needs the cd that says so"
    }
  ]
}
{
  "id": "shell-write-to-skill-scoped-path",
  "severity": "advisory",
  "since": "2026-09-14",
  "scope": "action",
  "failureMessage": "the pre-edit skill guard reads Edit, Write and NotebookEdit only, so a shell write carries its skill requirement to Stop, after the work the skill was there to shape",
