#!/usr/bin/env node
// Condense a captured conversation JSONL into a readable turn/action trace.
// usage: node condense.mjs <file> [--mode turns|tools|all] [--cap <chars>]
import { readFileSync } from 'node:fs';

const [, , file, ...rest] = process.argv;
const arg = (n, d) => { const i = rest.indexOf(n); return i === -1 ? d : rest[i + 1]; };
const mode = arg('--mode', 'all');
const cap = Number(arg('--cap', 400));

const clip = (s, n = cap) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > n ? `${t.slice(0, n)}…[${t.length}]` : t;
};

for (const line of readFileSync(file, 'utf8').split('\n')) {
  if (!line.trim()) continue;
  let e; try { e = JSON.parse(line); } catch { continue; }
  const ts = (e.timestamp || '').slice(11, 19);
  const msg = e.message ?? e;
  const role = msg.role || e.type;
  const content = msg.content;
  const parts = Array.isArray(content) ? content : [{ type: 'text', text: content }];
  for (const p of parts) {
    if (p.type === 'text' && p.text) {
      if (mode === 'tools') continue;
      console.log(`[${ts}] ${role}: ${clip(p.text, role === 'user' ? 2000 : cap)}`);
    } else if (p.type === 'tool_use') {
      if (mode === 'turns') continue;
      const i = p.input || {};
      const key = i.command ?? i.file_path ?? i.pattern ?? i.prompt ?? i.skill ?? i.body ?? JSON.stringify(i);
      console.log(`[${ts}]   -> ${p.name}(${clip(key, 220)})`);
    } else if (p.type === 'tool_result' && mode === 'all') {
      const c = Array.isArray(p.content) ? p.content.map((x) => x.text || '').join(' ') : p.content;
      const t = clip(c, 200);
      if (/error|denied|blocked|refus|fail/i.test(t)) console.log(`[${ts}]   <- RESULT ${t}`);
    }
  }
}

