17	  assert.deepEqual(judge('merge-main-into-branch', ['git merge origin/main', 'git rebase origin/main', 'git merge feature']), ['a merge of main into the branch']);
18	  assert.deepEqual(judge('github-api-via-shell', ['curl -s https://api.github.com/repos/o/r/pulls', 'gh pr view 1', 'git fetch origin', 'echo "see api.github.com"']), [
19	    'a GitHub read through the shell: "curl -s https://api.github.com"', 'a GitHub read through the shell: "gh "',
20	  ]);
21	  // A Monitor is a shell poll too: the same read through curl or gh, under a different tool.
22	  const monitor = declaredCheck('.claudinite/local/packs/claudinite', 'github-api-via-shell');
23	  const polled = makeTranscript([{ type: 'assistant', message: { content: [
24	    { type: 'tool_use', name: 'Monitor', input: { command: 'while true; do gh pr checks 1; sleep 30; done', description: 'ci', timeout_ms: 1000, persistent: false } },
